type AddressType = {
  city?: string | null
  country?: string | null
  line1?: string | null
  line2?: string | null
  postal_code?: string | null
  state?: string | null
}

const AddressSchema: z.ZodType<AddressType> = z
  .object({
    city: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'City, district, suburb, town, or village.' }),
    country: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Two-letter country code ([ISO 3166-1 alpha-2](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2)).',
      }),
    line1: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'Address line 1 (e.g., street, PO Box, or company name).' }),
    line2: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'Address line 2 (e.g., apartment, suite, unit, or building).' }),
    postal_code: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'ZIP or postal code.' }),
    state: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'State, county, province, or region.' }),
  })
  .openapi({ description: '', title: 'Address', 'x-expandableFields': [], required: [] })
  .openapi('Address')

type AccountBusinessProfileType = {
  mcc?: string | null
  name?: string | null
  product_description?: string | null
  support_address?: z.infer<typeof AddressSchema> | null
  support_email?: string | null
  support_phone?: string | null
  support_url?: string | null
  url?: string | null
}

const AccountBusinessProfileSchema: z.ZodType<AccountBusinessProfileType> = z
  .object({
    mcc: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '[The merchant category code for the account](https://stripe.com/docs/connect/setting-mcc). MCCs are used to classify businesses based on the goods or services they provide.',
      }),
    name: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'The customer-facing business name.' }),
    product_description: z
      .string()
      .max(40000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Internal-only description of the product sold or service provided by the business. It's used by Stripe for risk and underwriting purposes.",
      }),
    support_address: z
      .union([AddressSchema])
      .nullable()
      .exactOptional()
      .openapi({
        description: 'A publicly available mailing address for sending support issues to.',
      }),
    support_email: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description: 'A publicly available email address for sending support issues to.',
      }),
    support_phone: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'A publicly available phone number to call with support issues.' }),
    support_url: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'A publicly available website for handling support issues.' }),
    url: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: "The business's publicly available website." }),
  })
  .openapi({
    description: '',
    title: 'AccountBusinessProfile',
    'x-expandableFields': ['support_address'],
    required: [],
  })
  .openapi('AccountBusinessProfile')

