const FileSchema: z.ZodType<FileType> = z
  .lazy(() =>
    z
      .object({
        created: z
          .int()
          .openapi({
            description:
              'Time at which the object was created. Measured in seconds since the Unix epoch.',
          }),
        expires_at: z
          .int()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The time at which the file expires and is no longer available in epoch seconds.',
          }),
        filename: z
          .string()
          .max(5000)
          .nullable()
          .exactOptional()
          .openapi({
            description: 'A filename for the file, suitable for saving to a filesystem.',
          }),
        id: z.string().max(5000).openapi({ description: 'Unique identifier for the object.' }),
        links: z
          .object({
            data: z.array(FileLinkSchema).openapi({ description: 'Details about each object.' }),
            has_more: z
              .boolean()
              .openapi({
                description:
                  'True if this list has another page of items after this one that can be fetched.',
              }),
            object: z
              .literal('list')
              .openapi({
                description:
                  "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
              }),
            url: z
              .string()
              .regex(/^\/v1\/file_links/)
              .max(5000)
              .openapi({ description: 'The URL where this list can be accessed.' }),
          })
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'A list of [file links](https://stripe.com/docs/api#file_links) that point at this file.',
            required: ['data', 'has_more', 'object', 'url'],
            title: 'FileFileLinkList',
            'x-expandableFields': ['data'],
          }),
        object: z
          .literal('file')
          .openapi({
            description:
              "String representing the object's type. Objects of the same type share the same value.",
          }),
        purpose: z
          .enum([
            'account_requirement',
            'additional_verification',
            'business_icon',
            'business_logo',
            'customer_signature',
            'dispute_evidence',
            'document_provider_identity_document',
            'finance_report_run',
            'identity_document',
            'identity_document_downloadable',
            'pci_document',
            'selfie',
            'sigma_scheduled_query',
            'tax_document_user_upload',
            'terminal_reader_splashscreen',
          ])
          .openapi({
            description:
              'The [purpose](https://stripe.com/docs/file-upload#uploading-a-file) of the uploaded file.',
            'x-stripeBypassValidation': true,
          }),
        size: z.int().openapi({ description: 'The size in bytes of the file object.' }),
        title: z
          .string()
          .max(5000)
          .nullable()
          .exactOptional()
          .openapi({ description: 'A user friendly title for the document.' }),
        type: z
          .string()
          .max(5000)
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The type of the file returned (e.g., `csv`, `pdf`, `jpg`, or `png`).',
          }),
        url: z
          .string()
          .max(5000)
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The URL from which the file can be downloaded using your live secret API key.',
          }),
      })
      .openapi({
        description:
          "This is an object representing a file hosted on Stripe's servers. The\nfile may have been uploaded by yourself using the [create file](https://stripe.com/docs/api#create_file)\nrequest (for example, when uploading dispute evidence) or it may have\nbeen created by Stripe (for example, the results of a [Sigma scheduled\nquery](#scheduled_queries)).\n\nRelated guide: [File Upload Guide](https://stripe.com/docs/file-upload).",
        required: ['created', 'id', 'object', 'purpose', 'size'],
        title: 'File',
        'x-expandableFields': ['links'],
        'x-resourceId': 'file',
      }),
  )
  .openapi('File')

