type LegalEntityCompanyType = {
  address?: z.infer<typeof AddressSchema>
  address_kana?: z.infer<typeof LegalEntityJapanAddressSchema> | null
  address_kanji?: z.infer<typeof LegalEntityJapanAddressSchema> | null
  directors_provided?: boolean
  executives_provided?: boolean
  name?: string | null
  name_kana?: string | null
  name_kanji?: string | null
  owners_provided?: boolean
  ownership_declaration?: z.infer<typeof LegalEntityUboDeclarationSchema> | null
  phone?: string | null
  structure?:
    | 'free_zone_establishment'
    | 'free_zone_llc'
    | 'government_instrumentality'
    | 'governmental_unit'
    | 'incorporated_non_profit'
    | 'limited_liability_partnership'
    | 'llc'
    | 'multi_member_llc'
    | 'private_company'
    | 'private_corporation'
    | 'private_partnership'
    | 'public_company'
    | 'public_corporation'
    | 'public_partnership'
    | 'single_member_llc'
    | 'sole_establishment'
    | 'sole_proprietorship'
    | 'tax_exempt_government_instrumentality'
    | 'unincorporated_association'
    | 'unincorporated_non_profit'
  tax_id_provided?: boolean
  tax_id_registrar?: string
  vat_id_provided?: boolean
  verification?: z.infer<typeof LegalEntityCompanyVerificationSchema> | null
}

