const SetupIntentSchema: z.ZodType<SetupIntentType> = z
  .lazy(() =>
    z
      .object({
        application: z
          .union([z.string().max(5000), ApplicationSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'ID of the Connect application that created the SetupIntent.',
            'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/application' }] },
          }),
        attach_to_self: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              "If present, the SetupIntent's payment method will be attached to the in-context Stripe Account.\n\nIt can only be used for this Stripe Account’s own money movement flows like InboundTransfer and OutboundTransfers. It cannot be set to true when setting up a PaymentMethod for a Customer, and defaults to false when attaching a PaymentMethod to a Customer.",
          }),
        cancellation_reason: z
          .enum(['abandoned', 'duplicate', 'requested_by_customer'])
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'Reason for cancellation of this SetupIntent, one of `abandoned`, `requested_by_customer`, or `duplicate`.',
          }),
        client_secret: z
          .string()
          .max(5000)
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The client secret of this SetupIntent. Used for client-side retrieval using a publishable key.\n\nThe client secret can be used to complete payment setup from your frontend. It should not be stored, logged, or exposed to anyone other than the customer. Make sure that you have TLS enabled on any page that includes the client secret.',
          }),
        created: z
          .int()
          .openapi({
            description:
              'Time at which the object was created. Measured in seconds since the Unix epoch.',
          }),
        customer: z
          .union([z.string().max(5000), CustomerSchema, DeletedCustomerSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description:
              "ID of the Customer this SetupIntent belongs to, if one exists.\n\nIf present, the SetupIntent's payment method will be attached to the Customer on successful setup. Payment methods attached to other Customers cannot be used with this SetupIntent.",
            'x-expansionResources': {
              oneOf: [
                { $ref: '#/components/schemas/customer' },
                { $ref: '#/components/schemas/deleted_customer' },
              ],
            },
          }),
        description: z
          .string()
          .max(5000)
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'An arbitrary string attached to the object. Often useful for displaying to users.',
          }),
        flow_directions: z
          .array(z.enum(['inbound', 'outbound']))
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'Indicates the directions of money movement for which this payment method is intended to be used.\n\nInclude `inbound` if you intend to use the payment method as the origin to pull funds from. Include `outbound` if you intend to use the payment method as the destination to send funds to. You can include both if you intend to use the payment method for both purposes.',
          }),
        id: z.string().max(5000).openapi({ description: 'Unique identifier for the object.' }),
        last_setup_error: z
          .union([ApiErrorsSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The error encountered in the previous SetupIntent confirmation.',
          }),
        latest_attempt: z
          .union([z.string().max(5000), SetupAttemptSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The most recent SetupAttempt for this SetupIntent.',
            'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/setup_attempt' }] },
          }),
        livemode: z
          .boolean()
          .openapi({
            description:
              'Has the value `true` if the object exists in live mode or the value `false` if the object exists in test mode.',
          }),
        mandate: z
          .union([z.string().max(5000), MandateSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'ID of the multi use Mandate generated by the SetupIntent.',
            'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/mandate' }] },
          }),
        metadata: z
          .record(z.string(), z.string().max(500))
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
          }),
        next_action: z
          .union([SetupIntentNextActionSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'If present, this property tells you what actions you need to take in order for your customer to continue payment setup.',
          }),
        object: z
          .literal('setup_intent')
          .openapi({
            description:
              "String representing the object's type. Objects of the same type share the same value.",
          }),
        on_behalf_of: z
          .union([z.string().max(5000), AccountSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The account (if any) for which the setup is intended.',
            'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/account' }] },
          }),
        payment_method: z
          .union([z.string().max(5000), PaymentMethodSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'ID of the payment method used with this SetupIntent.',
            'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/payment_method' }] },
          }),
        payment_method_options: z
          .union([SetupIntentPaymentMethodOptionsSchema])
          .nullable()
          .exactOptional()
          .openapi({ description: 'Payment-method-specific configuration for this SetupIntent.' }),
        payment_method_types: z
          .array(z.string().max(5000))
          .openapi({
            description:
              'The list of payment method types (e.g. card) that this SetupIntent is allowed to set up.',
          }),
        single_use_mandate: z
          .union([z.string().max(5000), MandateSchema])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'ID of the single_use Mandate generated by the SetupIntent.',
            'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/mandate' }] },
          }),
        status: z
          .enum([
            'canceled',
            'processing',
            'requires_action',
            'requires_confirmation',
            'requires_payment_method',
            'succeeded',
          ])
          .openapi({
            description:
              '[Status](https://stripe.com/docs/payments/intents#intent-statuses) of this SetupIntent, one of `requires_payment_method`, `requires_confirmation`, `requires_action`, `processing`, `canceled`, or `succeeded`.',
          }),
        usage: z
          .string()
          .max(5000)
          .openapi({
            description:
              'Indicates how the payment method is intended to be used in the future.\n\nUse `on_session` if you intend to only reuse the payment method when the customer is in your checkout flow. Use `off_session` if your customer may or may not be in your checkout flow. If not provided, this value defaults to `off_session`.',
          }),
      })
      .openapi({
        description:
          "A SetupIntent guides you through the process of setting up and saving a customer's payment credentials for future payments.\nFor example, you could use a SetupIntent to set up and save your customer's card without immediately collecting a payment.\nLater, you can use [PaymentIntents](https://stripe.com/docs/api#payment_intents) to drive the payment flow.\n\nCreate a SetupIntent as soon as you're ready to collect your customer's payment credentials.\nDo not maintain long-lived, unconfirmed SetupIntents as they may no longer be valid.\nThe SetupIntent then transitions through multiple [statuses](https://stripe.com/docs/payments/intents#intent-statuses) as it guides\nyou through the setup process.\n\nSuccessful SetupIntents result in payment credentials that are optimized for future payments.\nFor example, cardholders in [certain regions](/guides/strong-customer-authentication) may need to be run through\n[Strong Customer Authentication](https://stripe.com/docs/strong-customer-authentication) at the time of payment method collection\nin order to streamline later [off-session payments](https://stripe.com/docs/payments/setup-intents).\nIf the SetupIntent is used with a [Customer](https://stripe.com/docs/api#setup_intent_object-customer), upon success,\nit will automatically attach the resulting payment method to that Customer.\nWe recommend using SetupIntents or [setup_future_usage](https://stripe.com/docs/api#payment_intent_object-setup_future_usage) on\nPaymentIntents to save payment methods in order to prevent saving invalid or unoptimized payment methods.\n\nBy using SetupIntents, you ensure that your customers experience the minimum set of required friction,\neven as regulations change over time.\n\nRelated guide: [Setup Intents API](https://stripe.com/docs/payments/setup-intents).",
        required: [
          'created',
          'id',
          'livemode',
          'object',
          'payment_method_types',
          'status',
          'usage',
        ],
        title: 'SetupIntent',
        'x-expandableFields': [
          'application',
          'customer',
          'last_setup_error',
          'latest_attempt',
          'mandate',
          'next_action',
          'on_behalf_of',
          'payment_method',
          'payment_method_options',
          'single_use_mandate',
        ],
        'x-resourceId': 'setup_intent',
      }),
  )
  .openapi('SetupIntent')

