type IssuingAuthorizationType = {
  amount: number
  amount_details?: z.infer<typeof IssuingAuthorizationAmountDetailsSchema> | null
  approved: boolean
  authorization_method: 'chip' | 'contactless' | 'keyed_in' | 'online' | 'swipe'
  balance_transactions: z.infer<typeof BalanceTransactionSchema>[]
  card: z.infer<typeof IssuingCardSchema>
  cardholder?: (string | z.infer<typeof IssuingCardholderSchema>) | null
  created: number
  currency: string
  id: string
  livemode: boolean
  merchant_amount: number
  merchant_currency: string
  merchant_data: z.infer<typeof IssuingAuthorizationMerchantDataSchema>
  metadata: { [key: string]: string }
  network_data?: z.infer<typeof IssuingAuthorizationNetworkDataSchema> | null
  object: 'issuing.authorization'
  pending_request?: z.infer<typeof IssuingAuthorizationPendingRequestSchema> | null
  request_history: z.infer<typeof IssuingAuthorizationRequestSchema>[]
  status: 'closed' | 'pending' | 'reversed'
  transactions: z.infer<typeof IssuingTransactionSchema>[]
  treasury?: z.infer<typeof IssuingAuthorizationTreasurySchema> | null
  verification_data: z.infer<typeof IssuingAuthorizationVerificationDataSchema>
  wallet?: string | null
}

