type IssuingCardType = {
  brand: string
  cancellation_reason?: 'design_rejected' | 'lost' | 'stolen' | null
  cardholder: z.infer<typeof IssuingCardholderSchema>
  created: number
  currency: string
  cvc?: string
  exp_month: number
  exp_year: number
  financial_account?: string | null
  id: string
  last4: string
  livemode: boolean
  metadata: { [key: string]: string }
  number?: string
  object: 'issuing.card'
  replaced_by?: (string | IssuingCardType) | null
  replacement_for?: (string | IssuingCardType) | null
  replacement_reason?: 'damaged' | 'expired' | 'lost' | 'stolen' | null
  shipping?: z.infer<typeof IssuingCardShippingSchema> | null
  spending_controls: z.infer<typeof IssuingCardAuthorizationControlsSchema>
  status: 'active' | 'canceled' | 'inactive'
  type: 'physical' | 'virtual'
  wallets?: z.infer<typeof IssuingCardWalletsSchema> | null
}

