export const postV1DisputesDisputeRoute = createRoute({
  method: 'post',
  path: '/v1/disputes/{dispute}',
  description:
    '<p>When you get a dispute, contacting your customer is always the best first step. If that doesn’t work, you can submit evidence to help us resolve the dispute in your favor. You can do this in your <a href="https://dashboard.stripe.com/disputes">dashboard</a>, but if you prefer, you can use the API to submit evidence programmatically.</p>\n\n<p>Depending on your dispute type, different evidence fields will give you a better chance of winning your dispute. To figure out which evidence fields to provide, see our <a href="/docs/disputes/categories">guide to dispute types</a>.</p>',
  operationId: 'PostDisputesDispute',
  request: {
    params: z.object({
      dispute: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'dispute',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              evidence: z
                .object({
                  access_activity_log: z.string().max(20000).exactOptional(),
                  billing_address: z.string().max(5000).exactOptional(),
                  cancellation_policy: z.string().exactOptional(),
                  cancellation_policy_disclosure: z.string().max(20000).exactOptional(),
                  cancellation_rebuttal: z.string().max(20000).exactOptional(),
                  customer_communication: z.string().exactOptional(),
                  customer_email_address: z.string().max(5000).exactOptional(),
                  customer_name: z.string().max(5000).exactOptional(),
                  customer_purchase_ip: z.string().max(5000).exactOptional(),
                  customer_signature: z.string().exactOptional(),
                  duplicate_charge_documentation: z.string().exactOptional(),
                  duplicate_charge_explanation: z.string().max(20000).exactOptional(),
                  duplicate_charge_id: z.string().max(5000).exactOptional(),
                  product_description: z.string().max(20000).exactOptional(),
                  receipt: z.string().exactOptional(),
                  refund_policy: z.string().exactOptional(),
                  refund_policy_disclosure: z.string().max(20000).exactOptional(),
                  refund_refusal_explanation: z.string().max(20000).exactOptional(),
                  service_date: z.string().max(5000).exactOptional(),
                  service_documentation: z.string().exactOptional(),
                  shipping_address: z.string().max(5000).exactOptional(),
                  shipping_carrier: z.string().max(5000).exactOptional(),
                  shipping_date: z.string().max(5000).exactOptional(),
                  shipping_documentation: z.string().exactOptional(),
                  shipping_tracking_number: z.string().max(5000).exactOptional(),
                  uncategorized_file: z.string().exactOptional(),
                  uncategorized_text: z.string().max(20000).exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Evidence to upload, to respond to a dispute. Updating any field in the hash will submit all fields in the hash for review. The combined character count of all fields is limited to 150,000.',
                  title: 'dispute_evidence_params',
                  required: [],
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              metadata: z
                .union([z.record(z.string(), z.string()), z.literal('')])
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              submit: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Whether to immediately submit evidence to the bank. If `false`, evidence is staged on the dispute. Staged evidence is visible in the API and Dashboard, and can be submitted to the bank by making another request with this attribute set to `true` (the default).',
                }),
            })
            .openapi({ required: [] }),
          encoding: { evidence: {}, expand: {}, metadata: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: DisputeSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

