export const postV1InvoicesInvoicePayRoute = createRoute({
  method: 'post',
  path: '/v1/invoices/{invoice}/pay',
  description:
    '<p>Stripe automatically creates and then attempts to collect payment on invoices for customers on subscriptions according to your <a href="https://dashboard.stripe.com/account/billing/automatic">subscriptions settings</a>. However, if you’d like to attempt payment on an invoice out of the normal collection schedule or for some other reason, you can do so.</p>',
  operationId: 'PostInvoicesInvoicePay',
  request: {
    params: z.object({
      invoice: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'invoice',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              forgive: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    "In cases where the source used to pay the invoice has insufficient funds, passing `forgive=true` controls whether a charge should be attempted for the full amount available on the source, up to the amount to fully pay the invoice. This effectively forgives the difference between the amount available on the source and the amount due. \n\nPassing `forgive=false` will fail the charge if the source hasn't been pre-funded with the right amount. An example for this case is with ACH Credit Transfers and wires: if the amount wired is less than the amount due by a small amount, you might want to forgive the difference. Defaults to `false`.",
                }),
              mandate: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    "ID of the mandate to be used for this invoice. It must correspond to the payment method used to pay the invoice, including the payment_method param or the invoice's default_payment_method or default_source, if set.",
                }),
              off_session: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Indicates if a customer is on or off-session while an invoice payment is attempted. Defaults to `true` (off-session).',
                }),
              paid_out_of_band: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Boolean representing whether an invoice is paid outside of Stripe. This will result in no charge being made. Defaults to `false`.',
                }),
              payment_method: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'A PaymentMethod to be charged. The PaymentMethod must be the ID of a PaymentMethod belonging to the customer associated with the invoice being paid.',
                }),
              source: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'A payment source to be charged. The source must be the ID of a source belonging to the customer associated with the invoice being paid.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { expand: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: InvoiceSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

