export const postV1PayoutsRoute = createRoute({
  method: 'post',
  path: '/v1/payouts',
  description:
    '<p>To send funds to your own bank account, you create a new payout object. Your <a href="#balance">Stripe balance</a> must be able to cover the payout amount, or you’ll receive an “Insufficient Funds” error.</p>\n\n<p>If your API key is in test mode, money won’t actually be sent, though everything else will occur as if in live mode.</p>\n\n<p>If you are creating a manual payout on a Stripe account that uses multiple payment source types, you’ll need to specify the source type balance that the payout should draw from. The <a href="#balance_object">balance object</a> details available and pending amounts by source type.</p>',
  operationId: 'PostPayouts',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({
                  description: 'A positive integer in cents representing how much to payout.',
                }),
              currency: z
                .string()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              description: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'An arbitrary string attached to the object. Often useful for displaying to users.',
                }),
              destination: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The ID of a bank account or a card to send the payout to. If no destination is supplied, the default external account for the specified currency will be used.',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              metadata: z
                .record(z.string(), z.string())
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              method: z
                .enum(['instant', 'standard'])
                .exactOptional()
                .openapi({
                  description:
                    'The method used to send this payout, which can be `standard` or `instant`. `instant` is only supported for payouts to debit cards. (See [Instant payouts for marketplaces for more information](https://stripe.com/blog/instant-payouts-for-marketplaces).)',
                  'x-stripeBypassValidation': true,
                }),
              source_type: z
                .enum(['bank_account', 'card', 'fpx'])
                .exactOptional()
                .openapi({
                  description:
                    'The balance type of your Stripe balance to draw this payout from. Balances for different payment sources are kept separately. You can find the amounts with the balances API. One of `bank_account`, `card`, or `fpx`.',
                  'x-stripeBypassValidation': true,
                }),
              statement_descriptor: z
                .string()
                .max(22)
                .exactOptional()
                .openapi({
                  description:
                    "A string to be displayed on the recipient's bank or card statement. This may be at most 22 characters. Attempting to use a `statement_descriptor` longer than 22 characters will return an error. Note: Most banks will truncate this information and/or display it inconsistently. Some may not display it at all.",
                  'x-stripeBypassValidation': true,
                }),
            })
            .openapi({ required: ['amount', 'currency'] }),
          encoding: { expand: {}, metadata: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: PayoutSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

