export const getV1PlansRoute = createRoute({
  method: 'get',
  path: '/v1/plans',
  description: '<p>Returns a list of your plans.</p>',
  operationId: 'GetPlans',
  request: {
    query: z.object({
      active: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Only return plans that are active or inactive (e.g., pass `false` to list all inactive plans).',
            in: 'query',
            name: 'active',
            required: false,
            schema: { type: 'boolean' },
            style: 'form',
          },
        }),
      created: z
        .union([
          z
            .object({
              gt: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              gte: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              lt: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              lte: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
            })
            .openapi({ title: 'range_query_specs', required: [] }),
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            z.int(),
          ),
        ])
        .exactOptional()
        .openapi({
          param: {
            description:
              'A filter on the list, based on the object `created` field. The value can be a string with an integer Unix timestamp, or it can be a dictionary with a number of different query options.',
            explode: true,
            in: 'query',
            name: 'created',
            required: false,
            schema: {
              anyOf: [
                {
                  properties: {
                    gt: { type: 'integer' },
                    gte: { type: 'integer' },
                    lt: { type: 'integer' },
                    lte: { type: 'integer' },
                  },
                  title: 'range_query_specs',
                  type: 'object',
                },
                { type: 'integer' },
              ],
            },
            style: 'deepObject',
          },
        }),
      ending_before: z
        .string()
        .max(5000)
        .exactOptional()
        .openapi({
          param: {
            description:
              'A cursor for use in pagination. `ending_before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, starting with `obj_bar`, your subsequent call can include `ending_before=obj_bar` in order to fetch the previous page of the list.',
            in: 'query',
            name: 'ending_before',
            required: false,
            schema: { maxLength: 5000, type: 'string' },
            style: 'form',
          },
        }),
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 10.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { type: 'integer' },
            style: 'form',
          },
        }),
      product: z
        .string()
        .max(5000)
        .exactOptional()
        .openapi({
          param: {
            description: 'Only return plans for the given product.',
            in: 'query',
            name: 'product',
            required: false,
            schema: { maxLength: 5000, type: 'string' },
            style: 'form',
          },
        }),
      starting_after: z
        .string()
        .max(5000)
        .exactOptional()
        .openapi({
          param: {
            description:
              'A cursor for use in pagination. `starting_after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with `obj_foo`, your subsequent call can include `starting_after=obj_foo` in order to fetch the next page of the list.',
            in: 'query',
            name: 'starting_after',
            required: false,
            schema: { maxLength: 5000, type: 'string' },
            style: 'form',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(PlanSchema).openapi({ description: 'Details about each object.' }),
              has_more: z
                .boolean()
                .openapi({
                  description:
                    'True if this list has another page of items after this one that can be fetched.',
                }),
              object: z
                .literal('list')
                .openapi({
                  description:
                    "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
                }),
              url: z
                .string()
                .regex(/^\/v1\/plans/)
                .max(5000)
                .openapi({ description: 'The URL where this list can be accessed.' }),
            })
            .openapi({
              description: '',
              required: ['data', 'has_more', 'object', 'url'],
              title: 'PlanList',
              'x-expandableFields': ['data'],
            }),
        },
      },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

export const postV1PlansRoute = createRoute({
  method: 'post',
  path: '/v1/plans',
  description:
    '<p>You can now model subscriptions more flexibly using the <a href="#prices">Prices API</a>. It replaces the Plans API and is backwards compatible to simplify your migration.</p>',
  operationId: 'PostPlans',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              active: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Whether the plan is currently available for new subscriptions. Defaults to `true`.',
                }),
              aggregate_usage: z
                .enum(['last_during_period', 'last_ever', 'max', 'sum'])
                .exactOptional()
                .openapi({
                  description:
                    'Specifies a usage aggregation strategy for plans of `usage_type=metered`. Allowed values are `sum` for summing up all usage during a period, `last_during_period` for using the last usage record reported within a period, `last_ever` for using the last usage record ever (across period bounds) or `max` which uses the usage record with the maximum reported usage during a period. Defaults to `sum`.',
                }),
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'A positive integer in cents (or local equivalent) (or 0 for a free plan) representing how much to charge on a recurring basis.',
                }),
              amount_decimal: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Same as `amount`, but accepts a decimal value with at most 12 decimal places. Only one of `amount` and `amount_decimal` can be set.',
                }),
              billing_scheme: z
                .enum(['per_unit', 'tiered'])
                .exactOptional()
                .openapi({
                  description:
                    'Describes how to compute the price per period. Either `per_unit` or `tiered`. `per_unit` indicates that the fixed amount (specified in `amount`) will be charged per unit in `quantity` (for plans with `usage_type=licensed`), or per unit of total usage (for plans with `usage_type=metered`). `tiered` indicates that the unit pricing will be computed using a tiering strategy as defined using the `tiers` and `tiers_mode` attributes.',
                }),
              currency: z
                .string()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              id: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'An identifier randomly generated by Stripe. Used to identify this plan when subscribing a customer. You can optionally override this ID, but the ID must be unique across all plans in your Stripe account. You can, however, use the same plan ID in both live and test modes.',
                }),
              interval: z
                .enum(['day', 'month', 'week', 'year'])
                .openapi({
                  description:
                    'Specifies billing frequency. Either `day`, `week`, `month` or `year`.',
                }),
              interval_count: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The number of intervals between subscription billings. For example, `interval=month` and `interval_count=3` bills every 3 months. Maximum of one year interval allowed (1 year, 12 months, or 52 weeks).',
                }),
              metadata: z
                .union([z.record(z.string(), z.string()), z.literal('')])
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              nickname: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description: 'A brief description of the plan, hidden from customers.',
                }),
              product: z
                .union([
                  z
                    .object({
                      active: z
                        .preprocess(
                          ((read) => (val: unknown) => {
                            const result = read.safeParse(val)
                            return result.success ? result.data : val
                          })(z.stringbool()),
                          z.boolean(),
                        )
                        .exactOptional(),
                      id: z.string().max(5000).exactOptional(),
                      metadata: z.record(z.string(), z.string()).exactOptional(),
                      name: z.string().max(5000),
                      statement_descriptor: z.string().max(22).exactOptional(),
                      tax_code: z.string().max(5000).exactOptional(),
                      unit_label: z.string().max(12).exactOptional(),
                    })
                    .openapi({
                      description:
                        'The product whose pricing the created plan will represent. This can either be the ID of an existing product, or a dictionary containing fields used to create a [service product](https://stripe.com/docs/api#product_object-type).',
                      required: ['name'],
                      title: 'inline_product_params',
                    }),
                  z
                    .string()
                    .max(5000)
                    .openapi({
                      description:
                        'The ID of the product whose pricing the created plan will represent.',
                    }),
                ])
                .exactOptional(),
              tiers: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(
                    z
                      .object({
                        flat_amount: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional(),
                        flat_amount_decimal: z.string().exactOptional(),
                        unit_amount: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional(),
                        unit_amount_decimal: z.string().exactOptional(),
                        up_to: ((schema) =>
                          z.union([
                            z.preprocess(
                              (val) =>
                                typeof val === 'string' &&
                                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                  ? Number(val)
                                  : val,
                              schema,
                            ),
                            schema,
                          ]))(z.union([z.literal('inf'), z.int()])),
                      })
                      .openapi({ required: ['up_to'], title: 'tier' }),
                  ),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Each element represents a pricing tier. This parameter requires `billing_scheme` to be set to `tiered`. See also the documentation for `billing_scheme`.',
                }),
              tiers_mode: z
                .enum(['graduated', 'volume'])
                .exactOptional()
                .openapi({
                  description:
                    'Defines if the tiering price should be `graduated` or `volume` based. In `volume`-based tiering, the maximum quantity within a period determines the per unit price, in `graduated` tiering pricing can successively change as the quantity grows.',
                }),
              transform_usage: z
                .object({
                  divide_by: z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    z.int(),
                  ),
                  round: z.enum(['down', 'up']),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Apply a transformation to the reported usage or set quantity before computing the billed price. Cannot be combined with `tiers`.',
                  required: ['divide_by', 'round'],
                  title: 'transform_usage_param',
                }),
              trial_period_days: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Default number of trial days when subscribing a customer to this plan using [`trial_from_plan=true`](https://stripe.com/docs/api#create_subscription-trial_from_plan).',
                }),
              usage_type: z
                .enum(['licensed', 'metered'])
                .exactOptional()
                .openapi({
                  description:
                    'Configures how the quantity per period should be determined. Can be either `metered` or `licensed`. `licensed` automatically bills the `quantity` set when adding it to a subscription. `metered` aggregates the total usage based on usage records. Defaults to `licensed`.',
                }),
            })
            .openapi({ required: ['currency', 'interval'] }),
          encoding: { expand: {}, metadata: {}, product: {}, tiers: {}, transform_usage: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: PlanSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

