export const postV1PromotionCodesRoute = createRoute({
  method: 'post',
  path: '/v1/promotion_codes',
  description:
    '<p>A promotion code points to a coupon. You can optionally restrict the code to a specific customer, redemption limit, and expiration date.</p>',
  operationId: 'PostPromotionCodes',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              active: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Whether the promotion code is currently active.' }),
              code: z
                .string()
                .max(500)
                .exactOptional()
                .openapi({
                  description:
                    'The customer-facing code. Regardless of case, this code must be unique across all active promotion codes for a specific customer. If left blank, we will generate one automatically.',
                }),
              coupon: z
                .string()
                .max(5000)
                .openapi({ description: 'The coupon for this promotion code.' }),
              customer: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'The customer that this promotion code can be used by. If not set, the promotion code can be used by all customers.',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              expires_at: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    "The timestamp at which this promotion code will expire. If the coupon has specified a `redeems_by`, then this value cannot be after the coupon's `redeems_by`.",
                }),
              max_redemptions: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    "A positive integer specifying the number of times the promotion code can be redeemed. If the coupon has specified a `max_redemptions`, then this value cannot be greater than the coupon's `max_redemptions`.",
                }),
              metadata: z
                .record(z.string(), z.string())
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              restrictions: z
                .object({
                  currency_options: z
                    .record(
                      z.string(),
                      z
                        .object({
                          minimum_amount: z
                            .preprocess(
                              (val) =>
                                typeof val === 'string' &&
                                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                  ? Number(val)
                                  : val,
                              z.int(),
                            )
                            .exactOptional(),
                        })
                        .openapi({ title: 'currency_option', required: [] }),
                    )
                    .exactOptional(),
                  first_time_transaction: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional(),
                  minimum_amount: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int(),
                    )
                    .exactOptional(),
                  minimum_amount_currency: z.string().exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description: 'Settings that restrict the redemption of the promotion code.',
                  title: 'restrictions_params',
                  required: [],
                }),
            })
            .openapi({ required: ['coupon'] }),
          encoding: { expand: {}, metadata: {}, restrictions: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: PromotionCodeSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

