export const postV1RefundsRoute = createRoute({
  method: 'post',
  path: '/v1/refunds',
  description: '<p>Create a refund.</p>',
  operationId: 'PostRefunds',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({ description: 'A positive integer representing how much to refund.' }),
              charge: z.string().max(5000).exactOptional(),
              currency: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              customer: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({ description: 'Customer whose customer balance to refund from.' }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              instructions_email: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Address to send refund email, use customer email if not specified',
                }),
              metadata: z
                .union([z.record(z.string(), z.string()), z.literal('')])
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              origin: z
                .literal('customer_balance')
                .exactOptional()
                .openapi({ description: 'Origin of the refund' }),
              payment_intent: z.string().max(5000).exactOptional(),
              reason: z.enum(['duplicate', 'fraudulent', 'requested_by_customer']).exactOptional(),
              refund_application_fee: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional(),
              reverse_transfer: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          encoding: { expand: {}, metadata: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: RefundSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

