export const getV1ReportingReportRunsReportRunRoute = createRoute({
  method: 'get',
  path: '/v1/reporting/report_runs/{report_run}',
  description: '<p>Retrieves the details of an existing Report Run.</p>',
  operationId: 'GetReportingReportRunsReportRun',
  request: {
    query: z.object({
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
    }),
    params: z.object({
      report_run: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'report_run',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: ReportingReportRunSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

