export const deleteV1SubscriptionsSubscriptionExposedIdRoute = createRoute({
  method: 'delete',
  path: '/v1/subscriptions/{subscription_exposed_id}',
  description:
    '<p>Cancels a customer’s subscription immediately. The customer will not be charged again for the subscription.</p>\n\n<p>Note, however, that any pending invoice items that you’ve created will still be charged for at the end of the period, unless manually <a href="#delete_invoiceitem">deleted</a>. If you’ve set the subscription to cancel at the end of the period, any pending prorations will also be left in place and collected at the end of the period. But if the subscription is set to cancel immediately, pending prorations will be removed.</p>\n\n<p>By default, upon subscription cancellation, Stripe will stop automatic collection of all finalized invoices for the customer. This is intended to prevent unexpected payment attempts after the customer has canceled a subscription. However, you can resume automatic collection of the invoices manually after subscription cancellation to have us proceed. Or, you could check for unpaid invoices before allowing the customer to cancel the subscription at all.</p>',
  operationId: 'DeleteSubscriptionsSubscriptionExposedId',
  request: {
    params: z.object({
      subscription_exposed_id: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'subscription_exposed_id',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              cancellation_details: z
                .object({
                  comment: z.string().max(5000).exactOptional(),
                  feedback: z
                    .enum([
                      '',
                      'customer_service',
                      'low_quality',
                      'missing_features',
                      'other',
                      'switched_service',
                      'too_complex',
                      'too_expensive',
                      'unused',
                    ])
                    .exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description: 'Details about why this subscription was cancelled',
                  title: 'cancellation_details_param',
                  required: [],
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              invoice_now: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Will generate a final invoice that invoices for any un-invoiced metered usage and new/pending proration invoice items.',
                }),
              prorate: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Will generate a proration invoice item that credits remaining unused time until the subscription period end.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { cancellation_details: {}, expand: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: SubscriptionSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

