export const postV1TestHelpersTreasuryReceivedCreditsRoute = createRoute({
  method: 'post',
  path: '/v1/test_helpers/treasury/received_credits',
  description:
    '<p>Use this endpoint to simulate a test mode ReceivedCredit initiated by a third party. In live mode, you can’t directly create ReceivedCredits initiated by third parties.</p>',
  operationId: 'PostTestHelpersTreasuryReceivedCredits',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({ description: 'Amount (in cents) to be transferred.' }),
              currency: z
                .string()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              description: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'An arbitrary string attached to the object. Often useful for displaying to users.',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              financial_account: z
                .string()
                .openapi({ description: 'The FinancialAccount to send funds to.' }),
              initiating_payment_method_details: z
                .object({
                  type: z.literal('us_bank_account'),
                  us_bank_account: z
                    .object({
                      account_holder_name: z.string().max(5000).exactOptional(),
                      account_number: z.string().max(5000).exactOptional(),
                      routing_number: z.string().max(5000).exactOptional(),
                    })
                    .exactOptional()
                    .openapi({ title: 'us_bank_account_source_params', required: [] }),
                })
                .exactOptional()
                .openapi({
                  description: 'Initiating payment method details for the object.',
                  required: ['type'],
                  title: 'source_params',
                }),
              network: z
                .enum(['ach', 'us_domestic_wire'])
                .openapi({ description: 'The rails used for the object.' }),
            })
            .openapi({ required: ['amount', 'currency', 'financial_account', 'network'] }),
          encoding: { expand: {}, initiating_payment_method_details: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: TreasuryReceivedCreditSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

