export const getV1TokensTokenRoute = createRoute({
  method: 'get',
  path: '/v1/tokens/{token}',
  description: '<p>Retrieves the token with the given ID.</p>',
  operationId: 'GetTokensToken',
  request: {
    query: z.object({
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
    }),
    params: z.object({
      token: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'token',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: TokenSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

