export const postV1TransfersIdReversalsRoute = createRoute({
  method: 'post',
  path: '/v1/transfers/{id}/reversals',
  description:
    '<p>When you create a new reversal, you must specify a transfer to create it on.</p>\n\n<p>When reversing transfers, you can optionally reverse part of the transfer. You can do so as many times as you wish until the entire transfer has been reversed.</p>\n\n<p>Once entirely reversed, a transfer can’t be reversed again. This method will return an error when called on an already-reversed transfer, or when trying to reverse more money than is left on a transfer.</p>',
  operationId: 'PostTransfersIdReversals',
  request: {
    params: z.object({
      id: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'A positive integer in cents (or local equivalent) representing how much of this transfer to reverse. Can only reverse up to the unreversed amount remaining of the transfer. Partial transfer reversals are only allowed for transfers to Stripe Accounts. Defaults to the entire transfer amount.',
                }),
              description: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'An arbitrary string which you can attach to a reversal object. It is displayed alongside the reversal in the Dashboard. This will be unset if you POST an empty value.',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              metadata: z
                .union([z.record(z.string(), z.string()), z.literal('')])
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://stripe.com/docs/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              refund_application_fee: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Boolean indicating whether the application fee should be refunded when reversing this transfer. If a full transfer reversal is given, the full application fee will be refunded. Otherwise, the application fee will be refunded with an amount proportional to the amount of the transfer reversed.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { expand: {}, metadata: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: TransferReversalSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

